<?php $publicTitle='CuePOS FAQ | Snooker Club Software Questions';$publicDescription='Answers to common CuePOS questions about trials, club data, live table operations, subscriptions and global deployment.';$publicCanonical=siteUrl('/faq.php');require __DIR__.'/includes/public-header.php';$faqs=[['Is CuePOS only for snooker clubs?','Yes. CuePOS is focused on snooker and cue-sports clubs, so the workflows, billing modes, player loyalty and tournament tools are built around this industry.'],['Can each club have its own private workspace?','Yes. Each club is a separate tenant with its own club settings, tables, staff, players, rates and operational records.'],['Is there a free trial?','Yes. New clubs can create a 14-day trial workspace. A payment method is not required during the trial.'],['Can I configure my local currency and time zone?','Yes. Every club can store its country, time zone, locale and currency settings, allowing the same platform to serve clubs in different markets.'],['Does CuePOS work on shared hosting?','The current PHP/MySQL deployment is designed to be compatible with shared hosting that supports PHP 8.x and MySQL 8.x. A managed cloud deployment may be used later for higher scale.'],['Will our private club data appear on Google?','No. Public marketing pages are indexable, while dashboards, APIs, member records and operational screens are explicitly marked and configured as non-indexable.']];$faqSchema=['@context'=>'https://schema.org','@type'=>'FAQPage','mainEntity'=>array_map(fn($f)=>['@type'=>'Question','name'=>$f[0],'acceptedAnswer'=>['@type'=>'Answer','text'=>$f[1]]],$faqs)]; ?><script type="application/ld+json"><?=json_encode($faqSchema,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><main class="max-w-4xl mx-auto px-5 py-20"><span class="eyebrow">FAQ</span><h1 class="font-display text-5xl font-extrabold mt-5">Questions club owners ask.</h1><div class="faq mt-12 space-y-3"><?php foreach($faqs as [$q,$a]): ?><details class="bg-white rounded-2xl border border-slate-200 p-6"><summary class="flex justify-between gap-4 font-display text-xl font-bold"><?=sanitize($q)?><i class="fa-solid fa-plus text-cue transition"></i></summary><p class="text-slate-600 leading-7 mt-4"><?=sanitize($a)?></p></details><?php endforeach; ?></div></main><?php require __DIR__.'/includes/public-footer.php'; ?>
